      <DataGridPremium
        {...data}
        loading={loading}
        slots={{ toolbar: CustomToolbar }}
        showToolbar
        initialState={{
          ...data.initialState,
          rowGrouping: {
            ...data.initialState?.rowGrouping,
            model: ['commodity'],
          },
